def next_bigger(num: int) -> int:
    """
    Returns the next higher number using the exact same set of digits as the original number.
    If no such number exists, return -1.
    """
    num_str = list(str(num))
    length = len(num_str)

    # Start from the end of the number
    for i in range(length - 2, -1, -1):
        if num_str[i] < num_str[i + 1]:
            break
    else:
        return -1  # no greater number can be formed

    # Find the smallest digit on the right side of (i) which is larger than num_str[i]
    for j in range(length - 1, i, -1):
        if num_str[j] > num_str[i]:
            num_str[i], num_str[j] = num_str[j], num_str[i]
            break

    # the digits after (i) must be reversed to get the next smallest number
    num_str = num_str[:i + 1] + sorted(num_str[i + 1:])

    return int("".join(num_str))
